// IconData::ToRGBA 方法实现
unsigned char* BitIcon_IconData::ToRGBA(bool invert) const {
    if (!this->bit_data || this->width <= 0 || this->height <= 0) {
        return nullptr;
    }
    
    int width = this->width;
    int height = this->height;
    int bits_len = width * height;
    int bytes_len = (bits_len + 7) / 8;
    
    // 分配RGBA缓冲区
    unsigned char* rgba = new unsigned char[width * height * 4];
    if (!rgba) {
        return nullptr;
    }
    
    int pixel_index = 0;
    for (int y = 0; y < height; y++) {
        for (int x = 0; x < width; x++) {
            int byte_idx = pixel_index / 8;
            int bit_idx = 7 - (pixel_index % 8);  // 高位在前
            
            int bit = (this->bit_data[byte_idx] >> bit_idx) & 1;
            if (invert) {
                bit = 1 - bit;
            }
            
            int rgba_idx = (y * width + x) * 4;
            
            if (bit) {
                // 不透明像素：白色
                rgba[rgba_idx] = 255;     // R
                rgba[rgba_idx + 1] = 255; // G
                rgba[rgba_idx + 2] = 255; // B
                rgba[rgba_idx + 3] = 255; // A
            } else {
                // 透明像素：全透明
                rgba[rgba_idx] = 0;       // R
                rgba[rgba_idx + 1] = 0;   // G
                rgba[rgba_idx + 2] = 0;   // B
                rgba[rgba_idx + 3] = 0;   // A
            }
            
            pixel_index++;
        }
    }
    
    return rgba;
}

// IconData::FreeRGBA 静态方法实现
void BitIcon_IconData::FreeRGBA(unsigned char* data) {
    delete[] data;
}

// 向后兼容的函数
unsigned char* decode_icon_to_rgba(const BitIcon_IconData& icon, bool invert) {
    return icon.ToRGBA(invert);
}

void free_icon_data(unsigned char* data) {
    BitIcon_IconData::FreeRGBA(data);
}

size_t get_icon_count() {
    return g_BitIcon_icon_count;
}

const BitIcon_IconData* get_icon_by_index(size_t index) {
    if (index >= g_BitIcon_icon_count) {
        return nullptr;
    }
    return g_BitIcon_icons[index];
}

const BitIcon_IconData* get_icon_by_name(const char* name) {
    for (size_t i = 0; i < g_BitIcon_icon_count; i++) {
        if (strcmp(g_BitIcon_icon_names[i], name) == 0) {
            return g_BitIcon_icons[i];
        }
    }
    return nullptr;
}
